import "server-only";
import { withAuth } from "@workos-inc/authkit-nextjs";
import type { User as WorkOSUser } from "@workos-inc/node";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

const users: User[] = [
  { id: "1", email: "ada@example.com", name: "Ada", createdAt: "2026-01-04" },
  { id: "2", email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
];

export async function listUsers(): Promise<User[]> {
  return users;
}

export async function getUser(id: string): Promise<User | undefined> {
  return users.find((u) => u.id === id);
}

// WorkOS is the source of truth for identity/credentials. This upserts the
// authenticated WorkOS user into Notely's own lightweight user directory
// (the one the "Team" list on the dashboard reads from) so the rest of the
// app can keep working with the plain `User` shape it already knows.
function syncUser(workosUser: WorkOSUser): User {
  const name =
    [workosUser.firstName, workosUser.lastName].filter(Boolean).join(" ") ||
    workosUser.email;

  const existing = users.find((u) => u.id === workosUser.id);
  if (existing) {
    existing.email = workosUser.email;
    existing.name = name;
    return existing;
  }

  const created: User = {
    id: workosUser.id,
    email: workosUser.email,
    name,
    createdAt: workosUser.createdAt,
  };
  users.push(created);
  return created;
}

// Returns the signed-in user, synced from the current WorkOS session, or
// undefined if nobody is signed in. Safe to call from public pages.
export async function getCurrentUser(): Promise<User | undefined> {
  const { user } = await withAuth();
  return user ? syncUser(user) : undefined;
}

// Same as getCurrentUser, but redirects to sign-in when nobody is signed in.
// Use this on pages that require an authenticated user, e.g. /dashboard.
export async function requireCurrentUser(): Promise<User> {
  const { user } = await withAuth({ ensureSignedIn: true });
  return syncUser(user);
}

